:root {
  color-scheme: light;
  font-family: Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
  color: #1e293b;
  background: #f4f6fa;
  font-synthesis: none;
}

* { box-sizing: border-box; }
body { margin: 0; min-width: 320px; }
.shell { width: min(760px, calc(100% - 40px)); margin: 0 auto; }
.topbar { height: 76px; display: flex; align-items: center; border-bottom: 1px solid #e2e8f0; }
.brand { color: #172554; font-size: 20px; font-weight: 750; letter-spacing: -0.04em; text-decoration: none; }
h1 { margin: 40px 0 26px; color: #172554; font-size: 32px; letter-spacing: -0.04em; }
.create-form { display: grid; grid-template-columns: 1fr auto; gap: 10px 12px; align-items: end; padding: 22px; background: white; border: 1px solid #e2e8f0; border-radius: 12px; box-shadow: 0 6px 18px #0f172a08; }
label { grid-column: 1 / -1; color: #475569; font-size: 14px; font-weight: 600; }
input { width: 100%; height: 44px; padding: 0 12px; border: 1px solid #cbd5e1; border-radius: 7px; font: inherit; outline: none; }
select { height: 40px; padding: 0 10px; border: 1px solid #cbd5e1; border-radius: 7px; background: white; color: inherit; font: inherit; }
input:focus { border-color: #4f46e5; box-shadow: 0 0 0 3px #4f46e526; }
button { height: 42px; padding: 0 16px; border: 0; border-radius: 7px; font: inherit; font-size: 14px; font-weight: 650; cursor: pointer; }
button:focus-visible, a:focus-visible { outline: 3px solid #818cf8; outline-offset: 3px; }
.primary { color: white; background: #4f46e5; }
.primary:hover { background: #4338ca; }
.secondary { color: #3730a3; background: #eef2ff; }
.secondary:hover { background: #e0e7ff; }
.project-list { display: grid; gap: 10px; margin-top: 20px; }
